import crypto from 'node:crypto';

export interface CrmQualifiedPayload {
  leadUuid: string;
  eventId: string;
  stage: 'QualifiedLead' | 'Schedule' | 'Purchase';
  phoneRaw: string;
  emailRaw?: string;
  fbc?: string;
  fbp?: string;
  metaLeadId?: string;
  clientIp?: string;
  userAgent?: string;
  valueVnd?: number;
  eventTimeUnix: number;
}

const sha256 = (val: string): string =>
  crypto.createHash('sha256').update(val.trim().toLowerCase()).digest('hex');

const normalizeVnPhoneForMeta = (raw: string): string => {
  const digits = raw.replace(/\D/g, '');
  if (digits.startsWith('0')) return `84${digits.slice(1)}`;
  return digits.startsWith('84') ? digits : `84${digits}`;
};

export async function sendCrmSignalToMetaCapi(
  pixelId: string,
  accessToken: string,
  lead: CrmQualifiedPayload
) {
  const userData: Record<string, unknown> = {
    ph: [sha256(normalizeVnPhoneForMeta(lead.phoneRaw))],
    external_id: [sha256(lead.leadUuid)],
  };
  if (lead.emailRaw) userData.em = [sha256(lead.emailRaw)];
  if (lead.fbc) userData.fbc = lead.fbc;
  if (lead.fbp) userData.fbp = lead.fbp;
  if (lead.metaLeadId) userData.lead_id = Number(lead.metaLeadId);
  if (lead.clientIp) userData.client_ip_address = lead.clientIp;
  if (lead.userAgent) userData.client_user_agent = lead.userAgent;

  const body = {
    data: [{
      event_name: lead.stage,
      event_time: lead.eventTimeUnix,
      event_id: lead.eventId,
      action_source: lead.metaLeadId ? 'system_generated' : 'website',
      user_data: userData,
      custom_data: {
        currency: 'VND',
        value: lead.valueVnd ?? 0,
        event_source: 'crm',
        lead_event_source: 'DOMATION_CRM_360',
      },
    }],
  };

  const res = await fetch(
    `https://graph.facebook.com/v21.0/${pixelId}/events?access_token=${accessToken}`,
    { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }
  );
  if (!res.ok) throw new Error(`Meta CAPI failed: ${res.status}`);
  return (await res.json()) as { events_received: number; fbtrace_id: string };
}
